INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jhard-0002','math','初中',0,'jkp-0343','short_answer',0.78,'（2024•成都）数学活动课上，同学们将两个全等的三角形纸片完全重合放置，固定一个顶点，然后将其中一个纸片绕这个顶点旋转，来探究图形旋转的性质．已知三角形纸片[IMG:jhard-0002-f1.png]和[IMG:jhard-0002-f2.png]中，[IMG:jhard-0002-f3.png]，[IMG:jhard-0002-f4.png]，[IMG:jhard-0002-f5.png]．【初步感知】（1）如图1，连接[IMG:jhard-0002-f6.png]，[IMG:jhard-0002-f7.png]，在纸片[IMG:jhard-0002-f8.png]绕点[IMG:jhard-0002-f9.png]旋转过程中，试探究[IMG:jhard-0002-f10.png]的值．【深入探究】（2）如图2，在纸片[IMG:jhard-0002-f11.png]绕点[IMG:jhard-0002-f12.png]旋转过程中，当点[IMG:jhard-0002-f13.png]恰好落在[IMG:jhard-0002-f14.png]的中线[IMG:jhard-0002-f15.png]的延长线上时，延长[IMG:jhard-0002-f16.png]交[IMG:jhard-0002-f17.png]于点[IMG:jhard-0002-f18.png]，求[IMG:jhard-0002-f19.png]的长．【拓展延伸】（3）在纸片[IMG:jhard-0002-f20.png]绕点[IMG:jhard-0002-f21.png]旋转过程中，试探究[IMG:jhard-0002-f22.png]，[IMG:jhard-0002-f23.png]，[IMG:jhard-0002-f24.png]三点能否构成直角三角形．若能，直接写出所有直角三角形[IMG:jhard-0002-f25.png]的面积；若不能，请说明理由．[IMG:jhard-0002-f26.png]','','','','imported-junior-hard','approved','通用','压轴');
