INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jhard-0021','math','初中',0,'jkp-0286','short_answer',0.78,'【定义】如果从一个平行四边形的一个顶点向不过该顶点的对角线作垂线，垂线交平行四边形的边于另一点，且该点为所在边的中点，那么这个平行四边形叫做“垂中平行四边形”，垂足叫做“垂中点”．如图1，在[IMG:jhard-0021-f1.png]中，[IMG:jhard-0021-f2.png]于点[IMG:jhard-0021-f3.png]，交[IMG:jhard-0021-f4.png]于点[IMG:jhard-0021-f5.png]，若[IMG:jhard-0021-f6.png]为[IMG:jhard-0021-f7.png]的中点，则[IMG:jhard-0021-f8.png]是垂中平行四边形，[IMG:jhard-0021-f9.png]是垂中点．【应用】（1）如图1，在垂中平行四边形[IMG:jhard-0021-f10.png]中，[IMG:jhard-0021-f11.png]是垂中点．若[IMG:jhard-0021-f12.png]，[IMG:jhard-0021-f13.png]，则[IMG:jhard-0021-f14.png]　　；[IMG:jhard-0021-f15.png]　　；（2）如图2，在垂中平行四边形[IMG:jhard-0021-f16.png]中，[IMG:jhard-0021-f17.png]是垂中点．若[IMG:jhard-0021-f18.png]，试猜想[IMG:jhard-0021-f19.png]与[IMG:jhard-0021-f20.png]的数量关系，并加以证明；（3）如图3，在△[IMG:jhard-0021-f21.png]中，[IMG:jhard-0021-f22.png]于点[IMG:jhard-0021-f23.png]，[IMG:jhard-0021-f24.png]，[IMG:jhard-0021-f25.png]．①请画出以[IMG:jhard-0021-f26.png]为边的垂中平行四边形，使得[IMG:jhard-0021-f27.png]为垂中点，点[IMG:jhard-0021-f28.png]在垂中平行四边形的边上；（不限定画图工具，不写画法及证明，在图上标明字母）②将△[IMG:jhard-0021-f29.png]沿[IMG:jhard-0021-f30.png]翻折得到△[IMG:jhard-0021-f31.png]，若射线[IMG:jhard-0021-f32.png]与①中所画的垂中平行四边形的边交于另一点[IMG:jhard-0021-f33.png]，连接[IMG:jhard-0021-f34.png]，请直接写出[IMG:jhard-0021-f35.png]的长．[IMG:jhard-0021-f36.png]','','','','imported-junior-hard','approved','通用','压轴');
