INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jhard-0023','math','初中',0,'jkp-0343','short_answer',0.78,'（2024•山西）综合与探究问题情境：如图1，四边形[IMG:jhard-0023-f1.png]是菱形，过点[IMG:jhard-0023-f2.png]作[IMG:jhard-0023-f3.png]于点[IMG:jhard-0023-f4.png]，过点[IMG:jhard-0023-f5.png]作[IMG:jhard-0023-f6.png]于点[IMG:jhard-0023-f7.png]．猜想证明：（1）判断四边形[IMG:jhard-0023-f8.png]的形状，并说明理由；深入探究：（2）将图1中的[IMG:jhard-0023-f9.png]绕点[IMG:jhard-0023-f10.png]逆时针旋转，得到[IMG:jhard-0023-f11.png]，点[IMG:jhard-0023-f12.png]，[IMG:jhard-0023-f13.png]的对应点分别为点[IMG:jhard-0023-f14.png]，[IMG:jhard-0023-f15.png]．①如图2，当线段[IMG:jhard-0023-f16.png]经过点[IMG:jhard-0023-f17.png]时，[IMG:jhard-0023-f18.png]所在直线分别与线段[IMG:jhard-0023-f19.png]，[IMG:jhard-0023-f20.png]交于点[IMG:jhard-0023-f21.png]，[IMG:jhard-0023-f22.png]．猜想线段[IMG:jhard-0023-f23.png]与[IMG:jhard-0023-f24.png]的数量关系，并说明理由；②当直线[IMG:jhard-0023-f25.png]与直线[IMG:jhard-0023-f26.png]垂直时，直线[IMG:jhard-0023-f27.png]分别与直线[IMG:jhard-0023-f28.png]，[IMG:jhard-0023-f29.png]交于点[IMG:jhard-0023-f30.png]，[IMG:jhard-0023-f31.png]，直线[IMG:jhard-0023-f32.png]与线段[IMG:jhard-0023-f33.png]交于点[IMG:jhard-0023-f34.png]．若[IMG:jhard-0023-f35.png]，[IMG:jhard-0023-f36.png]，直接写出四边形[IMG:jhard-0023-f37.png]的面积．[IMG:jhard-0023-f38.png]','','','','imported-junior-hard','approved','通用','压轴');
