INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jhard-0025','math','初中',0,'jkp-0268','short_answer',0.78,'（2024•河南）综合与实践在学习特殊四边形的过程中，我们积累了一定的研究经验．请运用已有经验，对“邻等对补四边形”进行研究．定义：至少有一组邻边相等且对角互补的四边形叫做邻等对补四边形．（1）操作判断用分别含有[IMG:jhard-0025-f1.png]和[IMG:jhard-0025-f2.png]角的直角三角形纸板拼出如图1所示的4个四边形，其中是邻等对补四边形的有 　　（填序号）．（2）性质探究根据定义可得出邻等对补四边形的边、角的性质．下面研究与对角线相关的性质．如图2，四边形[IMG:jhard-0025-f3.png]是邻等对补四边形，[IMG:jhard-0025-f4.png]，[IMG:jhard-0025-f5.png]是它的一条对角线．①写出图中相等的角，并说明理由；②若[IMG:jhard-0025-f6.png]，[IMG:jhard-0025-f7.png]，[IMG:jhard-0025-f8.png]，求[IMG:jhard-0025-f9.png]的长（用含[IMG:jhard-0025-f10.png]，[IMG:jhard-0025-f11.png]，[IMG:jhard-0025-f12.png]的式子表示）．（3）拓展应用如图3，在[IMG:jhard-0025-f13.png]△[IMG:jhard-0025-f14.png]中，[IMG:jhard-0025-f15.png]，[IMG:jhard-0025-f16.png]，[IMG:jhard-0025-f17.png]，分别在边[IMG:jhard-0025-f18.png]，[IMG:jhard-0025-f19.png]上取点[IMG:jhard-0025-f20.png]，[IMG:jhard-0025-f21.png]，使四边形[IMG:jhard-0025-f22.png]是邻等对补四边形．当该邻等对补四边形仅有一组邻边相等时，请直接写出[IMG:jhard-0025-f23.png]的长．[IMG:jhard-0025-f24.png]','','','','imported-junior-hard','approved','通用','压轴');
