INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jhard-0041','math','初中',0,'jkp-0396','short_answer',0.78,'（2024•成都）如图，在平面直角坐标系[IMG:jhard-0041-f1.png]中，抛物线[IMG:jhard-0041-f2.png]与[IMG:jhard-0041-f3.png]轴交于[IMG:jhard-0041-f4.png]，[IMG:jhard-0041-f5.png]两点（点[IMG:jhard-0041-f6.png]在点[IMG:jhard-0041-f7.png]的左侧），其顶点为[IMG:jhard-0041-f8.png]，[IMG:jhard-0041-f9.png]是抛物线第四象限上一点．（1）求线段[IMG:jhard-0041-f10.png]的长；（2）当[IMG:jhard-0041-f11.png]时，若[IMG:jhard-0041-f12.png]的面积与[IMG:jhard-0041-f13.png]的面积相等，求[IMG:jhard-0041-f14.png]的值；（3）延长[IMG:jhard-0041-f15.png]交[IMG:jhard-0041-f16.png]轴于点[IMG:jhard-0041-f17.png]，当[IMG:jhard-0041-f18.png]时，将[IMG:jhard-0041-f19.png]沿[IMG:jhard-0041-f20.png]方向平移得到△[IMG:jhard-0041-f21.png]．将抛物线[IMG:jhard-0041-f22.png]平移得到抛物线[IMG:jhard-0041-f23.png]，使得点[IMG:jhard-0041-f24.png]，[IMG:jhard-0041-f25.png]都落在抛物线[IMG:jhard-0041-f26.png]上．试判断抛物线[IMG:jhard-0041-f27.png]与[IMG:jhard-0041-f28.png]是否交于某个定点．若是，求出该定点坐标；若不是，请说明理由．','','','','imported-junior-hard','approved','通用','压轴');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jhard-0042','math','初中',0,'jkp-0396','short_answer',0.78,'（2024•绵阳）如图，抛物线[IMG:jhard-0042-f1.png]与[IMG:jhard-0042-f2.png]轴交于点[IMG:jhard-0042-f3.png]和[IMG:jhard-0042-f4.png]，与[IMG:jhard-0042-f5.png]轴交于点[IMG:jhard-0042-f6.png]，连接[IMG:jhard-0042-f7.png]和[IMG:jhard-0042-f8.png]，点[IMG:jhard-0042-f9.png]在抛物线上运动，连接[IMG:jhard-0042-f10.png]，[IMG:jhard-0042-f11.png]和[IMG:jhard-0042-f12.png]．（1）求抛物线的解析式，并写出其顶点坐标；（2）点[IMG:jhard-0042-f13.png]在抛物线上从点[IMG:jhard-0042-f14.png]运动到点[IMG:jhard-0042-f15.png]的过程中（点[IMG:jhard-0042-f16.png]与点[IMG:jhard-0042-f17.png]，[IMG:jhard-0042-f18.png]不重合），作点[IMG:jhard-0042-f19.png]关于[IMG:jhard-0042-f20.png]轴的对称点[IMG:jhard-0042-f21.png]，连接[IMG:jhard-0042-f22.png]，[IMG:jhard-0042-f23.png]，记△[IMG:jhard-0042-f24.png]的面积为[IMG:jhard-0042-f25.png]，记△[IMG:jhard-0042-f26.png]的面积为[IMG:jhard-0042-f27.png]，若满足[IMG:jhard-0042-f28.png]，求△[IMG:jhard-0042-f29.png]的面积；（3）在（2）的条件下，试探究在[IMG:jhard-0042-f30.png]轴上是否存在一点[IMG:jhard-0042-f31.png]，使得[IMG:jhard-0042-f32.png]？若存在，求出点[IMG:jhard-0042-f33.png]的坐标；若不存在，请说明理由．[IMG:jhard-0042-f34.png]','','','','imported-junior-hard','approved','通用','压轴');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jhard-0043','math','初中',0,'jkp-0396','short_answer',0.78,'（2024•赤峰）如图，是某公园的一种水上娱乐项目．数学兴趣小组对该项目中的数学问题进行了深入研究．下面是该小组绘制的水滑道截面图，如图1，人从点[IMG:jhard-0043-f1.png]处沿水滑道下滑至点[IMG:jhard-0043-f2.png]处腾空飞出后落入水池．以地面所在的水平线为[IMG:jhard-0043-f3.png]轴，过腾空点[IMG:jhard-0043-f4.png]与[IMG:jhard-0043-f5.png]轴垂直的直线为[IMG:jhard-0043-f6.png]轴，[IMG:jhard-0043-f7.png]为坐标原点，建立平面直角坐标系．他们把水滑道和人腾空飞出后经过的路径都近似看作是抛物线的一部分．根据测量和调查得到的数据和信息，设计了以下三个问题，请你解决．[IMG:jhard-0043-f8.png]（1）如图1，点[IMG:jhard-0043-f9.png]与地面的距离为2米，水滑道最低点[IMG:jhard-0043-f10.png]与地面的距离为[IMG:jhard-0043-f11.png]米，点[IMG:jhard-0043-f12.png]到点[IMG:jhard-0043-f13.png]的水平距离为3米，则水滑道[IMG:jhard-0043-f14.png]所在抛物线的解析式为 　　；（2）如图1，腾空点[IMG:jhard-0043-f15.png]与对面水池边缘的水平距离[IMG:jhard-0043-f16.png]米，人腾空后的落点[IMG:jhard-0043-f17.png]与水池边缘的安全距离[IMG:jhard-0043-f18.png]不少于3米．若某人腾空后的路径形成的抛物线[IMG:jhard-0043-f19.png]恰好与抛物线[IMG:jhard-0043-f20.png]关于点[IMG:jhard-0043-f21.png]成中心对称．①请直接写出此人腾空后的最大高度和抛物线[IMG:jhard-0043-f22.png]的解析式；②此人腾空飞出后的落点[IMG:jhard-0043-f23.png]是否在安全范围内？请说明理由（水面与地面之间的高度差忽略不计）；（3）为消除安全隐患，公园计划对水滑道进行加固．如图2，水滑道已经有两条加固钢架，一条是水滑道距地面4米的点[IMG:jhard-0043-f24.png]处竖直支撑的钢架[IMG:jhard-0043-f25.png]，另一条是点[IMG:jhard-0043-f26.png]与点[IMG:jhard-0043-f27.png]之间连接支撑的钢架[IMG:jhard-0043-f28.png]．现在需要在水滑道下方加固一条支撑钢架，为了美观，要求这条钢架与[IMG:jhard-0043-f29.png]平行，且与水滑道有唯一公共点，一端固定在钢架[IMG:jhard-0043-f30.png]上，另一端固定在地面上．请你计算出这条钢架的长度（结果保留根号）．','','','','imported-junior-hard','approved','通用','压轴');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jhard-0044','math','初中',0,'jkp-0396','short_answer',0.78,'（2024•山西）综合与实践问题情境：如图1，矩形[IMG:jhard-0044-f1.png]是学校花园的示意图，其中一个花坛的轮廓可近似看成由抛物线的一部分与线段[IMG:jhard-0044-f2.png]组成的封闭图形，点[IMG:jhard-0044-f3.png]，[IMG:jhard-0044-f4.png]在矩形的边[IMG:jhard-0044-f5.png]上．现要对该花坛内种植区域进行划分，以种植不同花卉，学校面向全体同学征集设计方案．方案设计：如图2，[IMG:jhard-0044-f6.png]米，[IMG:jhard-0044-f7.png]的垂直平分线与抛物线交于点[IMG:jhard-0044-f8.png]，与[IMG:jhard-0044-f9.png]交于点[IMG:jhard-0044-f10.png]，点[IMG:jhard-0044-f11.png]是抛物线的顶点，且[IMG:jhard-0044-f12.png]米．欣欣设计的方案如下：第一步：在线段[IMG:jhard-0044-f13.png]上确定点[IMG:jhard-0044-f14.png]，使[IMG:jhard-0044-f15.png]，用篱笆沿线段[IMG:jhard-0044-f16.png]，[IMG:jhard-0044-f17.png]分隔出△[IMG:jhard-0044-f18.png]区域，种植串串红；第二步：在线段[IMG:jhard-0044-f19.png]上取点[IMG:jhard-0044-f20.png]（不与[IMG:jhard-0044-f21.png]，[IMG:jhard-0044-f22.png]重合），过点[IMG:jhard-0044-f23.png]作[IMG:jhard-0044-f24.png]的平行线，交抛物线于点[IMG:jhard-0044-f25.png]，[IMG:jhard-0044-f26.png]．用篱笆沿[IMG:jhard-0044-f27.png]，[IMG:jhard-0044-f28.png]将线段[IMG:jhard-0044-f29.png]，[IMG:jhard-0044-f30.png]与抛物线围成的区域分隔成三部分，分别种植不同花色的月季．方案实施：学校采用了欣欣的方案，在完成第一步△[IMG:jhard-0044-f31.png]区域的分隔后，发现仅剩6米篱笆材料．若要在第二步分隔中恰好用完6米材料，需确定[IMG:jhard-0044-f32.png]与[IMG:jhard-0044-f33.png]的长．为此，欣欣在图2中以[IMG:jhard-0044-f34.png]所在直线为[IMG:jhard-0044-f35.png]轴，[IMG:jhard-0044-f36.png]所在直线为[IMG:jhard-0044-f37.png]轴建立平面直角坐标系．请按照她的方法解决问题：（1）在图2中画出坐标系，并求抛物线的函数表达式；（2）求6米材料恰好用完时[IMG:jhard-0044-f38.png]与[IMG:jhard-0044-f39.png]的长；（3）种植区域分隔完成后，欣欣又想用灯带对该花坛进行装饰，计划将灯带围成一个矩形．她尝试借助图2设计矩形四个顶点的位置，其中两个顶点在抛物线上，另外两个顶点分别在线段[IMG:jhard-0044-f40.png]，[IMG:jhard-0044-f41.png]上．直接写出符合设计要求的矩形周长的最大值．[IMG:jhard-0044-f42.png]','','','','imported-junior-hard','approved','通用','压轴');
