INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jhard-0048','math','初中',0,'jkp-0396','short_answer',0.78,'（2024•日照）已知二次函数[IMG:jhard-0048-f1.png]为常数）．（1）求证：不论[IMG:jhard-0048-f2.png]为何值，该二次函数图象与[IMG:jhard-0048-f3.png]轴总有两个公共点；（2）当[IMG:jhard-0048-f4.png]时，该二次函数的最大值与最小值之差为9，求此时函数的解析式；（3）若二次函数图象对称轴为直线[IMG:jhard-0048-f5.png]，该函数图象与[IMG:jhard-0048-f6.png]轴交于[IMG:jhard-0048-f7.png]，[IMG:jhard-0048-f8.png]两点（点[IMG:jhard-0048-f9.png]在点[IMG:jhard-0048-f10.png]左侧），与[IMG:jhard-0048-f11.png]轴交于点[IMG:jhard-0048-f12.png]．点[IMG:jhard-0048-f13.png]关于对称轴的对称点为[IMG:jhard-0048-f14.png]，点[IMG:jhard-0048-f15.png]为[IMG:jhard-0048-f16.png]的中点，过点[IMG:jhard-0048-f17.png]的直线[IMG:jhard-0048-f18.png]（直线[IMG:jhard-0048-f19.png]不过[IMG:jhard-0048-f20.png]，[IMG:jhard-0048-f21.png]两点）与二次函数图象交于[IMG:jhard-0048-f22.png]，[IMG:jhard-0048-f23.png]两点，直线[IMG:jhard-0048-f24.png]与直线[IMG:jhard-0048-f25.png]相交于点[IMG:jhard-0048-f26.png]．①求证：点[IMG:jhard-0048-f27.png]在一条定直线上；②若[IMG:jhard-0048-f28.png]，请直接写出满足条件的直线[IMG:jhard-0048-f29.png]的解析式，不必说明理由．[IMG:jhard-0048-f30.png]','','','','imported-junior-hard','approved','通用','压轴');
