INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jhard-0055','math','初中',0,'jkp-0357','short_answer',0.78,'对于凸四边形，根据它有无外接圆（四个顶点都在同一个圆上）与内切圆（四条边都与同一个圆相切），可分为四种类型，我们不妨约定：既无外接圆，又无内切圆的四边形称为“平凡型无圆”四边形：只有外接圆，而无内切圆的四边形称为“外接型单圆”四边形；只有内切圆，而无外接圆的四边形称为“内切型单圆”四边形：既有外接圆，又有内切圆的四边形称为“完美型双圆”四边形．请你根据该约定，解答下列问题：（1）请你判断下列说法是否正确（在题后相应的括号中，正确的打“[IMG:jhard-0055-f1.png]”，错误的打“[IMG:jhard-0055-f2.png]” [IMG:jhard-0055-f3.png]．①平行四边形一定不是“平凡型无圆”四边形； 　　②内角不等于[IMG:jhard-0055-f4.png]的菱形一定是“内切型单圆”四边形； 　　③若“完美型双圆”四边形的外接圆圆心与内切圆圆心重合，外接圆半径为[IMG:jhard-0055-f5.png]，内切圆半径为[IMG:jhard-0055-f6.png]，则有[IMG:jhard-0055-f7.png]． 　　（2）如图1，已知四边形[IMG:jhard-0055-f8.png]内接于[IMG:jhard-0055-f9.png]，四条边长满足：[IMG:jhard-0055-f10.png]．①该四边形[IMG:jhard-0055-f11.png]是“　　”四边形（从约定的四种类型中选一种填入）；②若[IMG:jhard-0055-f12.png]的平分线[IMG:jhard-0055-f13.png]交[IMG:jhard-0055-f14.png]于点[IMG:jhard-0055-f15.png]，[IMG:jhard-0055-f16.png]的平分线[IMG:jhard-0055-f17.png]交[IMG:jhard-0055-f18.png]于点[IMG:jhard-0055-f19.png]，连接[IMG:jhard-0055-f20.png]．求证：[IMG:jhard-0055-f21.png]是[IMG:jhard-0055-f22.png]的直径．[IMG:jhard-0055-f23.png]（3）已知四边形[IMG:jhard-0055-f24.png]是“完美型双圆”四边形，它的内切圆[IMG:jhard-0055-f25.png]与[IMG:jhard-0055-f26.png]，[IMG:jhard-0055-f27.png]，[IMG:jhard-0055-f28.png]，[IMG:jhard-0055-f29.png]分别相切于点[IMG:jhard-0055-f30.png]，[IMG:jhard-0055-f31.png]，[IMG:jhard-0055-f32.png]，[IMG:jhard-0055-f33.png]．①如图2，连接[IMG:jhard-0055-f34.png]，[IMG:jhard-0055-f35.png]交于点[IMG:jhard-0055-f36.png]．求证：[IMG:jhard-0055-f37.png]；②如图3，连接[IMG:jhard-0055-f38.png]，[IMG:jhard-0055-f39.png]，[IMG:jhard-0055-f40.png]，[IMG:jhard-0055-f41.png]，若[IMG:jhard-0055-f42.png]，[IMG:jhard-0055-f43.png]，[IMG:jhard-0055-f44.png]，求内切圆[IMG:jhard-0055-f45.png]的半径[IMG:jhard-0055-f46.png]及[IMG:jhard-0055-f47.png]的长．','','','','imported-junior-hard','approved','通用','压轴');
