INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jhard-0183','math','初中',0,'jkp-0281','short_answer',0.78,'（2025•广西）【平行六边形】如图1，在凸六边形[IMG:jhard-0183-f1.png]中，满足[IMG:jhard-0183-f2.png]，[IMG:jhard-0183-f3.png]，[IMG:jhard-0183-f4.png]，我们称这样的凸六边形叫做“平行六边形”．其中[IMG:jhard-0183-f5.png]与[IMG:jhard-0183-f6.png]，[IMG:jhard-0183-f7.png]与[IMG:jhard-0183-f8.png]，[IMG:jhard-0183-f9.png]与[IMG:jhard-0183-f10.png]叫做“主对边”； [IMG:jhard-0183-f11.png]和[IMG:jhard-0183-f12.png]，[IMG:jhard-0183-f13.png]和[IMG:jhard-0183-f14.png]，[IMG:jhard-0183-f15.png]和[IMG:jhard-0183-f16.png]叫做“主对角”； [IMG:jhard-0183-f17.png]，[IMG:jhard-0183-f18.png]，[IMG:jhard-0183-f19.png]叫做“主对角线”．（1）类比平行四边形性质，有如下猜想，请判断正误并在横线上填写“正确”或“错误”．猜想判断正误①平行六边形的三组主对边分别相等         　　        ②平行六边形的三组主对角分别相等         　　        ③平行六边形的三条主对角线互相平分         　　        【菱六边形】六条边都相等的平行六边形叫做“菱六边形”．（2）如图2，已知平行六边形[IMG:jhard-0183-f20.png]满足[IMG:jhard-0183-f21.png]．求证：平行六边形[IMG:jhard-0183-f22.png]是菱六边形；（3）如图3是一张边长为3，4，6的三角形纸片．剪裁掉三个小三角形，使剪裁后的纸片为菱六边形．请在剪裁掉的小三角形中，任选一个，求它的各边长．[IMG:jhard-0183-f23.png]','','','','imported-junior-hard','approved','通用','压轴');
