INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jhard-0201','math','初中',0,'jkp-0286','short_answer',0.78,'（2025•苏州）两个智能机器人在如图所示的[IMG:jhard-0201-f1.png]△[IMG:jhard-0201-f2.png]区域工作，[IMG:jhard-0201-f3.png]，[IMG:jhard-0201-f4.png]，[IMG:jhard-0201-f5.png]，直线[IMG:jhard-0201-f6.png]为生产流水线，且[IMG:jhard-0201-f7.png]平分△[IMG:jhard-0201-f8.png]的面积（即[IMG:jhard-0201-f9.png]为[IMG:jhard-0201-f10.png]中点）．机器人甲从点[IMG:jhard-0201-f11.png]出发，沿[IMG:jhard-0201-f12.png]的方向以[IMG:jhard-0201-f13.png]的速度匀速运动，其所在位置用点[IMG:jhard-0201-f14.png]表示，机器人乙从点[IMG:jhard-0201-f15.png]出发，沿[IMG:jhard-0201-f16.png]的方向以[IMG:jhard-0201-f17.png]的速度匀速运动，其所在位置用点[IMG:jhard-0201-f18.png]表示．两个机器人同时出发，设机器人运动的时间为[IMG:jhard-0201-f19.png]，记点[IMG:jhard-0201-f20.png]到[IMG:jhard-0201-f21.png]的距离（即垂线段[IMG:jhard-0201-f22.png]的长）为[IMG:jhard-0201-f23.png]，点[IMG:jhard-0201-f24.png]到[IMG:jhard-0201-f25.png]的距离（即垂线段[IMG:jhard-0201-f26.png]的长）为[IMG:jhard-0201-f27.png]．当机器人乙到达终点时，两个机器人立即同时停止运动，此时[IMG:jhard-0201-f28.png]．[IMG:jhard-0201-f29.png]与[IMG:jhard-0201-f30.png]的部分对应数值如表[IMG:jhard-0201-f31.png][IMG:jhard-0201-f32.png]0[IMG:jhard-0201-f33.png][IMG:jhard-0201-f34.png]','','','','imported-junior-hard','approved','通用','压轴');
