INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jhard-0203','math','初中',0,'jkp-0167','short_answer',0.78,'（2025•广东）《九章算术》是世界上较早给出勾股数公式的著作，掌握确定勾股数组的方法对研究直角三角形具有重要意义．若直角三角形的三边长[IMG:jhard-0203-f1.png]，[IMG:jhard-0203-f2.png]，[IMG:jhard-0203-f3.png]都是正整数，则[IMG:jhard-0203-f4.png]，[IMG:jhard-0203-f5.png]，[IMG:jhard-0203-f6.png]为一组“勾股数”．如表中的每一组数都是勾股数．3，4，57，24，2511，60，6115，112，11319，180，1814，3，58，15，1712，35，3716，63，6520，21，295，12，139，12，1513，84，8517，144，14521，28，356，8，1010，　　 ，2614，48，5018，80，8222，120，122（1）请补全如表中的勾股数．（2）根据如表中数据规律，用含字母（均为正整数）的代数式分别表示[IMG:jhard-0203-f7.png]，[IMG:jhard-0203-f8.png]，[IMG:jhard-0203-f9.png]，使该组代数式能表示上表中所有的勾股数，并证明．（3）某校计划在一块绿地上种花，使之构成如图所示的图案，该图案是由四个全等的直角三角形组成．种花要求：仅在三角形边上种花，每个三角形顶点处都种一株花，各边上相邻两株花之间的距离均为[IMG:jhard-0203-f10.png]．如果每个三角形最短边都种21株花，那么这块绿地最少需要种植多少株花？[IMG:jhard-0203-f11.png]','','','','imported-junior-hard','approved','通用','压轴');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jhard-0204','math','初中',0,'jkp-0396','short_answer',0.78,'（2025•山西）综合与实践问题情境：青蛙腾空阶段的运动路线可看作抛物线．我国某科研团队根据青蛙的生物特征和运动机理设计出了仿青蛙机器人，其起跳后的运动路线与实际情况中青蛙腾空阶段的运动路线相吻合．实验数据：仿青蛙机器人从水平地面起跳，并落在水平地面上，其运动路线的最高点距地面[IMG:jhard-0204-f1.png]，起跳点与落地点的距离为[IMG:jhard-0204-f2.png]．数学建模：如图1，将仿青蛙机器人的运动路线抽象为抛物线，其顶点为[IMG:jhard-0204-f3.png]，对称轴为直线[IMG:jhard-0204-f4.png]，仿青蛙机器人在水平地面上的起跳点为[IMG:jhard-0204-f5.png]，落地点为[IMG:jhard-0204-f6.png]．以[IMG:jhard-0204-f7.png]为原点，[IMG:jhard-0204-f8.png]所在直线为[IMG:jhard-0204-f9.png]轴，过点[IMG:jhard-0204-f10.png]与[IMG:jhard-0204-f11.png]所在水平地面垂直的直线为[IMG:jhard-0204-f12.png]轴，建立平面直角坐标系．[IMG:jhard-0204-f13.png]（1）请直接写出顶点[IMG:jhard-0204-f14.png]的坐标，并求该抛物线的函数表达式；问题解决：已知仿青蛙机器人起跳后的运动路线形状保持不变，即抛物线的形状不变．（2）如图1，若仿青蛙机器人从点[IMG:jhard-0204-f15.png]正上方的点[IMG:jhard-0204-f16.png]处起跳，落地点为[IMG:jhard-0204-f17.png]，点[IMG:jhard-0204-f18.png]的坐标为[IMG:jhard-0204-f19.png]，点[IMG:jhard-0204-f20.png]在[IMG:jhard-0204-f21.png]轴的正半轴上．求起跳点[IMG:jhard-0204-f22.png]与落地点[IMG:jhard-0204-f23.png]的水平距离[IMG:jhard-0204-f24.png]的长；（3）实验表明：仿青蛙机器人在跃过障碍物时，与障碍物上表面的每个点在竖直方向上的距离不少于[IMG:jhard-0204-f25.png]，才能安全通过．如图2，水平地面上有一个障碍物，其纵切面为四边形[IMG:jhard-0204-f26.png]，其中[IMG:jhard-0204-f27.png]，[IMG:jhard-0204-f28.png]，[IMG:jhard-0204-f29.png]，[IMG:jhard-0204-f30.png]．仿青蛙机器人从距离[IMG:jhard-0204-f31.png]左侧[IMG:jhard-0204-f32.png]处的地面起跳，发现不能安全通过该障碍物．若团队人员在起跳处放置一个平台，仿青蛙机器人从平台上起跳，则刚好安全通过该障碍物．请直接写出该平台的高度（平台的大小忽略不计，障碍物的纵切面与仿青蛙机器人的运动路线在同一竖直平面内）．','','','','imported-junior-hard','approved','通用','压轴');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jhard-0205','math','初中',0,'jkp-0286','short_answer',0.78,'（2025•陕西）问题探究（1）如图①，在△[IMG:jhard-0205-f1.png]中，请画出一个[IMG:jhard-0205-f2.png]，使得点[IMG:jhard-0205-f3.png]，[IMG:jhard-0205-f4.png]，[IMG:jhard-0205-f5.png]分别在边[IMG:jhard-0205-f6.png]，[IMG:jhard-0205-f7.png]，[IMG:jhard-0205-f8.png]上；（2）如图②，在矩形[IMG:jhard-0205-f9.png]中，[IMG:jhard-0205-f10.png]，[IMG:jhard-0205-f11.png]，[IMG:jhard-0205-f12.png]为矩形[IMG:jhard-0205-f13.png]内一点，且满足[IMG:jhard-0205-f14.png]，△[IMG:jhard-0205-f15.png]周长的最小值；问题解决（3）为了进一步提升游客的体验感，某公园管理部门准备在花海边沿与游客服务中心之间的草地上选址修建一条笔直的步道及一个观景台．如图③所示，△[IMG:jhard-0205-f16.png]区域为草地，线段[IMG:jhard-0205-f17.png]为花海边沿，点[IMG:jhard-0205-f18.png]为游客服务中心，线段[IMG:jhard-0205-f19.png]为步道，点[IMG:jhard-0205-f20.png]和点[IMG:jhard-0205-f21.png]为步道口，点[IMG:jhard-0205-f22.png]为观景台．按照设计要求，点[IMG:jhard-0205-f23.png]，[IMG:jhard-0205-f24.png]分别在边[IMG:jhard-0205-f25.png]，[IMG:jhard-0205-f26.png]上，且满足[IMG:jhard-0205-f27.png]，[IMG:jhard-0205-f28.png]为[IMG:jhard-0205-f29.png]的中点，为保证观赏花海的最佳效果，还需使[IMG:jhard-0205-f30.png]最大．已知[IMG:jhard-0205-f31.png]，[IMG:jhard-0205-f32.png]，请你帮助公园管理部门确定观景台的位置（在图中画出符合条件的点），并计算此时步道口[IMG:jhard-0205-f33.png]与游客服务中心[IMG:jhard-0205-f34.png]之间的距离[IMG:jhard-0205-f35.png]．（步道的宽及步道口、观景台、游客服务中心的大小均忽略不计）[IMG:jhard-0205-f36.png]','','','','imported-junior-hard','approved','通用','压轴');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jhard-0206','math','初中',0,'jkp-0396','short_answer',0.78,'（2025•齐齐哈尔）2025年春晚舞台上的机器人表演，充分演绎了科技与民族文化的完美融合．为满足学生的好奇心和求知欲，某校组织科技活动“机器人走进校园”， [IMG:jhard-0206-f1.png]热情瞬间燃爆．校园里一条笔直的“勤学路”上依次设置了[IMG:jhard-0206-f2.png]，[IMG:jhard-0206-f3.png]，[IMG:jhard-0206-f4.png]三个互动区，机器人甲、乙分别从[IMG:jhard-0206-f5.png]，[IMG:jhard-0206-f6.png]两区同时出发开始表演，机器人甲沿“勤学路”以20米[IMG:jhard-0206-f7.png]分的速度匀速向[IMG:jhard-0206-f8.png]区行进，行至[IMG:jhard-0206-f9.png]区时停留4.5分钟（与师生热情互动）后，继续沿“勤学路”向[IMG:jhard-0206-f10.png]区匀速行进，机器人乙沿“勤学路”以10米[IMG:jhard-0206-f11.png]分的速度匀速向[IMG:jhard-0206-f12.png]区行进，行至[IMG:jhard-0206-f13.png]区时接到指令立即匀速返回，结果两机器人同时到达[IMG:jhard-0206-f14.png]区．机器人甲、乙距[IMG:jhard-0206-f15.png]区的距离[IMG:jhard-0206-f16.png]（米[IMG:jhard-0206-f17.png]与机器人乙行进的时间[IMG:jhard-0206-f18.png]（分[IMG:jhard-0206-f19.png]之间的函数关系如图所示．请结合图象信息解答下列问题：（1）[IMG:jhard-0206-f20.png]，[IMG:jhard-0206-f21.png]两区相距 　　 米，[IMG:jhard-0206-f22.png] 　　 ；（2）求线段[IMG:jhard-0206-f23.png]所在直线的函数解析式；（3）机器人乙行进的时间为多少分时，机器人甲、乙相距30米？（直接写出答案即可）[IMG:jhard-0206-f24.png]','','','','imported-junior-hard','approved','通用','压轴');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jhard-0207','math','初中',0,'jkp-0396','short_answer',0.78,'（2025•内蒙古）问题背景：综合与实践课上，老师让同学们设计一个家电装置图案，某小组设计的效果图如图1所示．[IMG:jhard-0207-f1.png]外形参数：如图2，装置整体图案为轴对称图形，外形由上方的抛物线[IMG:jhard-0207-f2.png]，中间的矩形[IMG:jhard-0207-f3.png]和下方的抛物线[IMG:jhard-0207-f4.png]组成．抛物线[IMG:jhard-0207-f5.png]的高度为[IMG:jhard-0207-f6.png]，矩形[IMG:jhard-0207-f7.png]的边[IMG:jhard-0207-f8.png]，[IMG:jhard-0207-f9.png]，抛物线[IMG:jhard-0207-f10.png]的高度为[IMG:jhard-0207-f11.png]．在装置内部安装矩形电子显示屏[IMG:jhard-0207-f12.png]，点[IMG:jhard-0207-f13.png]，[IMG:jhard-0207-f14.png]在抛物线[IMG:jhard-0207-f15.png]上，点[IMG:jhard-0207-f16.png]，[IMG:jhard-0207-f17.png]在抛物线[IMG:jhard-0207-f18.png]上．问题解决：如图3，该小组以矩形[IMG:jhard-0207-f19.png]的顶点[IMG:jhard-0207-f20.png]为原点，以[IMG:jhard-0207-f21.png]边所在的直线为[IMG:jhard-0207-f22.png]轴，以[IMG:jhard-0207-f23.png]边所在的直线为[IMG:jhard-0207-f24.png]轴，建立平面直角坐标系．请结合外形参数，完成以下任务：（1）直接写出[IMG:jhard-0207-f25.png]，[IMG:jhard-0207-f26.png]，[IMG:jhard-0207-f27.png]三点的坐标；（2）直接写出抛物线[IMG:jhard-0207-f28.png]和[IMG:jhard-0207-f29.png]的顶点坐标，并分别求出抛物线[IMG:jhard-0207-f30.png]和[IMG:jhard-0207-f31.png]的函数表达式；（3）为满足矩形电子显示屏[IMG:jhard-0207-f32.png]的空间要求，需要[IMG:jhard-0207-f33.png]边的长为[IMG:jhard-0207-f34.png]，求此时[IMG:jhard-0207-f35.png]边的长．','','','','imported-junior-hard','approved','通用','压轴');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jhard-0208','math','初中',0,'jkp-0281','short_answer',0.78,'（2025•广西）综合与实践树人中学组织一次“爱心义卖”活动．九（5）班分配到了一块矩形义卖区和一把遮阳伞，遮阳伞在地面上的投影是一个平行四边形（如图[IMG:jhard-0208-f1.png]．初始时，矩形义卖区[IMG:jhard-0208-f2.png]与遮阳伞投影[IMG:jhard-0208-f3.png]的平面图如图2所示，[IMG:jhard-0208-f4.png]在[IMG:jhard-0208-f5.png]上，[IMG:jhard-0208-f6.png]，[IMG:jhard-0208-f7.png]，[IMG:jhard-0208-f8.png]，[IMG:jhard-0208-f9.png]，[IMG:jhard-0208-f10.png]．由于场地限制，参加义卖的同字只能左右平移遮阳伞．在移动过程中，[IMG:jhard-0208-f11.png]也随之移动[IMG:jhard-0208-f12.png]始终在[IMG:jhard-0208-f13.png]边所在直线1．且形状大小保持不变，但落在义卖区内的部分（遮阳区）会呈现不同的形状．如图3为[IMG:jhard-0208-f14.png]移动到[IMG:jhard-0208-f15.png]落在[IMG:jhard-0208-f16.png]上的情形．[IMG:jhard-0208-f17.png]【问题提出】西西同学打算用数学方法，确定遮阳区面积最大时[IMG:jhard-0208-f18.png]的位置．设遮阳区的面积为[IMG:jhard-0208-f19.png] [IMG:jhard-0208-f20.png]，[IMG:jhard-0208-f21.png]从初始时向右移动的距离为[IMG:jhard-0208-f22.png] [IMG:jhard-0208-f23.png]．【直观感知】（1）从初始起右移至图3情形的过程中，[IMG:jhard-0208-f24.png]随[IMG:jhard-0208-f25.png]的增大如何变化？【初步探究】（2）求图3情形的[IMG:jhard-0208-f26.png]与[IMG:jhard-0208-f27.png]的值；【深入研究】（3）从图3情形起右移至[IMG:jhard-0208-f28.png]与[IMG:jhard-0208-f29.png]重合，求该过程中[IMG:jhard-0208-f30.png]关于[IMG:jhard-0208-f31.png]的解析式；【问题解决】（4）当遮阳区面积最大时，[IMG:jhard-0208-f32.png]向右移动了多少？（直接写出结果）','','','','imported-junior-hard','approved','通用','压轴');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jhard-0209','math','初中',0,'jkp-0396','short_answer',0.78,'（2025•深圳）综合与实践【问题背景】排队是生活中常见的场景．如图，某数学小组针对某次演出，研究了排队人数与安检时间，安排通道数之间的关系．【研究条件】条件1：观众进场立即排队安检，在任意时刻都满足：排队人数[IMG:jhard-0209-f1.png]现场总人数[IMG:jhard-0209-f2.png]已入场人数；条件2：若该演出场地最多可开放9条安检通道，平均每条通道每分钟可安检6人．【模型构建】若该演出前30分钟开始进行安检，经研究发现，现场总人数[IMG:jhard-0209-f3.png]与安检时间[IMG:jhard-0209-f4.png]之间满足关系式：[IMG:jhard-0209-f5.png]．结合上述信息，请完成下述问题：（1）当开通3条安检通道时，安检时间[IMG:jhard-0209-f6.png]分钟时，已入场人数为　　 ，排队人数[IMG:jhard-0209-f7.png]与安检时间[IMG:jhard-0209-f8.png]的函数关系式为　　 ．【模型应用】（2）在（1）的条件下，排队人数在第几分钟达到最大值，最大人数为多少？（3）已知该演出主办方要求：①排队人数在安检开始10分钟内（包含10分钟）减少；②尽量少安排安检通道，以节省开支．若同时满足以上两个要求，可开设几条安检通道，请说明理由？【总结反思】函数可刻画生活实际场景，但要注意验证模型的正确性，未来可结合更多变量（如突发情况、安检流程优化等）进行更深入的分析，以提高模型的准确性和实用性．[IMG:jhard-0209-f9.png]','','','','imported-junior-hard','approved','通用','压轴');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jhard-0210','math','初中',0,'jkp-0396','short_answer',0.78,'（2025•吉林）【知识链接】实验目的：探究浮力的大小与哪些因素有关实验过程：如图①，在两个完全相同的溢水杯中，分别盛满甲、乙两种不同密度的液体，将完全相同的两个质地均匀的圆柱体小铝块分别悬挂在弹簧测力计[IMG:jhard-0210-f1.png]、[IMG:jhard-0210-f2.png]的下方，从离桌面[IMG:jhard-0210-f3.png]的高度，分别缓慢浸入到甲、乙两种液体中，通过观察弹簧测力计示数的变化，探究浮力大小的变化．（溢水杯的杯底厚度忽略不计）实验结论：物体在液体中所受浮力的大小，跟它浸在液体中的体积有关、跟液体的密度有关．物体浸在液体中的体积越大、液体的密度越大，浮力就越大．总结公式：当小铝块位于液面上方时，[IMG:jhard-0210-f4.png]；当小铝块浸入液面后，[IMG:jhard-0210-f5.png]．【建立模型】在实验探究的过程中，实验小组发现：弹簧测力计[IMG:jhard-0210-f6.png]，[IMG:jhard-0210-f7.png]各自的示数[IMG:jhard-0210-f8.png]与小铝块各自下降的高度[IMG:jhard-0210-f9.png]之间的关系如图②所示．【解决问题】（1）当小铝块下降[IMG:jhard-0210-f10.png]时，直接写出弹簧测力计[IMG:jhard-0210-f11.png]和弹簧测力计[IMG:jhard-0210-f12.png]的示数．（2）当[IMG:jhard-0210-f13.png]时，求弹簧测力计[IMG:jhard-0210-f14.png]的示数[IMG:jhard-0210-f15.png]关于[IMG:jhard-0210-f16.png]的函数解析式．（3）当弹簧测力计[IMG:jhard-0210-f17.png]悬挂的小铝块下降[IMG:jhard-0210-f18.png]时，甲液体中的小铝块受到的浮力为[IMG:jhard-0210-f19.png]，若使乙液体中的小铝块所受的浮力也为[IMG:jhard-0210-f20.png]，则乙液体中小铝块浸入的深度为[IMG:jhard-0210-f21.png]，直接写出[IMG:jhard-0210-f22.png]，[IMG:jhard-0210-f23.png]的值．[IMG:jhard-0210-f24.png]','','','','imported-junior-hard','approved','通用','压轴');
