INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jhard-0215','math','初中',0,'jkp-0396','short_answer',0.78,'（2025•广州）某玩转数学小组发现隧道前通常设有涉水线和限高架等安全警示，为探究其内在的数学原理，该小组考察了如图1所示的双向通行隧道．以下为该小组研究报告的部分记录，请认真阅读，解决问题．发现问题确定目标涉水线设置限高架设置数学抽象绘制图形         [IMG:jhard-0215-f1.png]         隧道及斜坡的侧面示意图可近似如图2所示．         [IMG:jhard-0215-f2.png]         图3为隧道横截面示意图，由抛物线的一部分[IMG:jhard-0215-f3.png]和矩形[IMG:jhard-0215-f4.png]的三边构成．信息收集资料整理当隧道内积水的水深为0.27米时（即积水达到涉水线处），车辆应避免通行．车辆进入隧道，应在行驶车道内通行（禁止压线），且必须保证车辆顶部与隧道顶部[IMG:jhard-0215-f5.png]在竖直方向的空隙不小于0.3米．实地考察数据采集斜坡的坡角[IMG:jhard-0215-f6.png]为[IMG:jhard-0215-f7.png]，并查得[IMG:jhard-0215-f8.png]，[IMG:jhard-0215-f9.png]，[IMG:jhard-0215-f10.png]．隧道的最高点[IMG:jhard-0215-f11.png]到地面[IMG:jhard-0215-f12.png]距离为5.4米，两侧墙面高[IMG:jhard-0215-f13.png]米，地面跨度[IMG:jhard-0215-f14.png]米．车辆行驶方向的右侧车道线（宽度忽略不计）与墙面的距离为1米．问题解决：（1）如图2，求涉水线离坡底的距离[IMG:jhard-0215-f15.png]（精确到0.01米）；（2）在图3中建立适当的平面直角坐标系，求抛物线[IMG:jhard-0215-f16.png]的解析式；（3）限高架上标有警示语“车辆限高[IMG:jhard-0215-f17.png]米”（即最大安全限商），求[IMG:jhard-0215-f18.png]的值（精确到1米）．[IMG:jhard-0215-f19.png]★类型：圆综合（8题）★','','','','imported-junior-hard','approved','通用','压轴');
