INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jhard-0220','math','初中',0,'jkp-0296','short_answer',0.78,'（2025•青海）活动与探究解码蜜蜂的“家”——为什么蜂房是正六边形的？蜜蜂的“集体宿舍”是由多个正六边形密铺在一起的，这些密铺的正六边形使得蜂房之间没有空隙，一点儿也不浪费空间．这是数学中的密铺（或镶嵌）问题．平面图形的密铺（或镶嵌）是指用形状、大小完全相同的一种或多种平面图形进行拼接，使彼此之间不留空隙、不重叠地铺成一片．探究一：若只用一种正多边形，哪些正多边形可以密铺？平面图形每个内角度数能否整除能否密铺正三角形[IMG:jhard-0220-f1.png][IMG:jhard-0220-f2.png]能正方形①②能正五边形[IMG:jhard-0220-f3.png][IMG:jhard-0220-f4.png]不能正六边形[IMG:jhard-0220-f5.png][IMG:jhard-0220-f6.png]能正七边形[IMG:jhard-0220-f7.png][IMG:jhard-0220-f8.png]不能正八边形[IMG:jhard-0220-f9.png]③④[IMG:jhard-0220-f10.png][IMG:jhard-0220-f11.png][IMG:jhard-0220-f12.png][IMG:jhard-0220-f13.png]（1）请补全上述表格①　　 ；②　　 ；③　　 ；④　　 ．探究二：在能密铺的正多边形中，哪种形状最省材料？数学视角：蜜蜂的身体可近似看成圆柱，若圆柱底面半径为1，当蜂房恰好容纳一只蜜蜂即正多边形的内切圆半径均为1时，比较正三角形，正方形和正六边形周长的大小．观察图1，发现[IMG:jhard-0220-f14.png]是正三角形[IMG:jhard-0220-f15.png]的内切圆，与[IMG:jhard-0220-f16.png]切于点[IMG:jhard-0220-f17.png]，[IMG:jhard-0220-f18.png]，[IMG:jhard-0220-f19.png]，[IMG:jhard-0220-f20.png]，在[IMG:jhard-0220-f21.png]△[IMG:jhard-0220-f22.png]中，[IMG:jhard-0220-f23.png]，则△[IMG:jhard-0220-f24.png]的周长为[IMG:jhard-0220-f25.png]．（2）如图2，正方形[IMG:jhard-0220-f26.png]的周长为 　　 ；（3）如图3，求出正六边形的周长（写出求解过程）．探究三：在能密铺的正多边形中，哪种形状可以使蜜蜂的活动空间最大？数学视角：假设蜜蜂建造蜂房的材料总量即周长一定，比较正三角形、正方形和正六边形面积的大小．（4）若正多边形的周长都为12，则正三角形的面积为 　　 ；正方形的面积为 　　 ；正六边形的面积为 　　 ．【得出结论】综上所述：在相同条件下，正六边形结构最省材料，能使蜜蜂的活动空间最大，是建造蜂房的最优方案．[IMG:jhard-0220-f27.png]','','','','imported-junior-hard','approved','通用','压轴');
