INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jhard-0228','math','初中',0,'jkp-0396','short_answer',0.78,'（2025•长沙）我们约定：当[IMG:jhard-0228-f1.png]，[IMG:jhard-0228-f2.png]，[IMG:jhard-0228-f3.png]，[IMG:jhard-0228-f4.png]满足[IMG:jhard-0228-f5.png]，且[IMG:jhard-0228-f6.png]时，称点[IMG:jhard-0228-f7.png]，[IMG:jhard-0228-f8.png]与点[IMG:jhard-0228-f9.png]，[IMG:jhard-0228-f10.png]为一对“对偶点”．若某函数图象上至少存在一对“对偶点”，就称该函数为“对偶函数”．请你根据该约定，解答下列问题：（1）请你判断下列说法是否正确（在题后相应的括号中，正确的打“[IMG:jhard-0228-f11.png]”，错误的打“[IMG:jhard-0228-f12.png]” [IMG:jhard-0228-f13.png]；①函数[IMG:jhard-0228-f14.png]是非零常数）的图象上存在无数对“对偶点”；　　 ②函数[IMG:jhard-0228-f15.png]一定不是“对偶函数”；　　 ③函数[IMG:jhard-0228-f16.png]的图象上至少存在两对“对偶点”．　　 （2）若关于[IMG:jhard-0228-f17.png]的一次函数[IMG:jhard-0228-f18.png]与[IMG:jhard-0228-f19.png]，[IMG:jhard-0228-f20.png]都是常数，且[IMG:jhard-0228-f21.png]均是“对偶函数”，求这两个函数的图象分别与两坐标轴围成的平面图形的面积之和；（3）若关于[IMG:jhard-0228-f22.png]的二次函数[IMG:jhard-0228-f23.png]是“对偶函数”，求实数[IMG:jhard-0228-f24.png]的取值范围．','','','','imported-junior-hard','approved','通用','压轴');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jhard-0229','math','初中',0,'jkp-0288','short_answer',0.78,'（2025•长春）数学活动：探究平面图形的最小覆盖圆【定义】我们称能完全覆盖某平面图形的圆（即该平面图形上所有的点均在圆内或圆上）为该平面图形的覆盖圆．其中，能完全覆盖平面图形的最小的圆（即直径最小）称为该平面图形的最小覆盖圆．【探究一】线段的最小覆盖圆线段[IMG:jhard-0229-f1.png]的覆盖圆有无数个，其中，以[IMG:jhard-0229-f2.png]为直径的圆是其最小覆盖圆．理由如下：易知线段[IMG:jhard-0229-f3.png]的最小覆盖圆一定经过点[IMG:jhard-0229-f4.png]、点[IMG:jhard-0229-f5.png]．如图①，以[IMG:jhard-0229-f6.png]为直径作[IMG:jhard-0229-f7.png]，再过[IMG:jhard-0229-f8.png]、[IMG:jhard-0229-f9.png]两点作[IMG:jhard-0229-f10.png]与[IMG:jhard-0229-f11.png]不重合），连结[IMG:jhard-0229-f12.png]，[IMG:jhard-0229-f13.png]．在△[IMG:jhard-0229-f14.png]中，有[IMG:jhard-0229-f15.png]▲[IMG:jhard-0229-f16.png]．[IMG:jhard-0229-f17.png]，[IMG:jhard-0229-f18.png]，即[IMG:jhard-0229-f19.png]的直径大于[IMG:jhard-0229-f20.png]的直径．[IMG:jhard-0229-f21.png]是线段[IMG:jhard-0229-f22.png]的最小覆盖圆．“▲”处应填写的推理依据为 　　 ．【探究二】直角三角形的最小覆盖圆要确定直角三角形的最小覆盖圆，我们可先将其转化为【探究一】中线段的最小覆盖圆问题．这样就可以先确定直角三角形最长边（斜边）的最小覆盖圆，再判断直角顶点与这个圆的位置关系，从而确定直角三角形的最小覆盖圆．如图②，在[IMG:jhard-0229-f23.png]△[IMG:jhard-0229-f24.png]中，[IMG:jhard-0229-f25.png]．[IMG:jhard-0229-f26.png]是以[IMG:jhard-0229-f27.png]为直径的圆．请你判断点[IMG:jhard-0229-f28.png]与[IMG:jhard-0229-f29.png]的位置关系，并说明理由．又由【探究一】可知，[IMG:jhard-0229-f30.png]是[IMG:jhard-0229-f31.png]△[IMG:jhard-0229-f32.png]最长边[IMG:jhard-0229-f33.png]的最小覆盖圆，所以，[IMG:jhard-0229-f34.png]是[IMG:jhard-0229-f35.png]△[IMG:jhard-0229-f36.png]的最小覆盖圆．【拓展应用】矩形的最小覆盖圆如图③，在矩形[IMG:jhard-0229-f37.png]中，[IMG:jhard-0229-f38.png]，[IMG:jhard-0229-f39.png]．（1）用圆规和无刻度的直尺在图③中作矩形[IMG:jhard-0229-f40.png]的最小覆盖圆；（不写作法，保留作图痕迹，作图确定后必须用黑色字迹的签字笔描黑）（2）该矩形[IMG:jhard-0229-f41.png]的最小覆盖圆的直径为 　　[IMG:jhard-0229-f42.png]；（3）若用两个等圆完全覆盖矩形[IMG:jhard-0229-f43.png]，则这样的两个等圆的最小直径为 　　[IMG:jhard-0229-f44.png]．[IMG:jhard-0229-f45.png]','','','','imported-junior-hard','approved','通用','压轴');
