INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jhard-0247','math','初中',0,'jkp-0396','short_answer',0.78,'（2025•大庆）如图，已知二次函数[IMG:jhard-0247-f1.png]图象的对称轴为[IMG:jhard-0247-f2.png]轴，且过坐标原点[IMG:jhard-0247-f3.png]及点[IMG:jhard-0247-f4.png]，过点[IMG:jhard-0247-f5.png]作射线[IMG:jhard-0247-f6.png]平行于[IMG:jhard-0247-f7.png]轴（点[IMG:jhard-0247-f8.png]在点[IMG:jhard-0247-f9.png]上方），点[IMG:jhard-0247-f10.png]坐标为[IMG:jhard-0247-f11.png]，连接[IMG:jhard-0247-f12.png]并延长交抛物线于点[IMG:jhard-0247-f13.png]，射线[IMG:jhard-0247-f14.png]平分[IMG:jhard-0247-f15.png]，过点[IMG:jhard-0247-f16.png]作[IMG:jhard-0247-f17.png]的垂线[IMG:jhard-0247-f18.png]交[IMG:jhard-0247-f19.png]轴于点[IMG:jhard-0247-f20.png]．（1）求二次函数的表达式；（2）判断直线[IMG:jhard-0247-f21.png]与二次函数[IMG:jhard-0247-f22.png]的图象的公共点的个数，并说明理由；（3）点[IMG:jhard-0247-f23.png]为[IMG:jhard-0247-f24.png]轴上的一个动点，且[IMG:jhard-0247-f25.png]为钝角，请直接写出实数[IMG:jhard-0247-f26.png]的取值范围．[IMG:jhard-0247-f27.png]','','','','imported-junior-hard','approved','通用','压轴');
