INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jhard-0250','math','初中',0,'jkp-0396','short_answer',0.78,'（2025•宿迁）定义：在平面直角坐标系中，到两个坐标轴的距离都小于或等于[IMG:jhard-0250-f1.png]的点叫“[IMG:jhard-0250-f2.png]阶近轴点”，所有的“[IMG:jhard-0250-f3.png]阶近轴点”组成的图形记为图形[IMG:jhard-0250-f4.png]．如图所示，所有的“1阶近轴点”组成的图形是以坐标原点为中心，2为边长的正方形区域．（1）下列函数图象上存在“1阶近轴点”的是  ；①[IMG:jhard-0250-f5.png]；②[IMG:jhard-0250-f6.png]；③[IMG:jhard-0250-f7.png]．（2）若一次函数[IMG:jhard-0250-f8.png]的图象上存在“3阶近轴点”，求实数[IMG:jhard-0250-f9.png]的取值范围；（3）特别地，当点[IMG:jhard-0250-f10.png]在图形[IMG:jhard-0250-f11.png]上，且横坐标是纵坐标的[IMG:jhard-0250-f12.png]倍时，称点[IMG:jhard-0250-f13.png]是图形[IMG:jhard-0250-f14.png]的“[IMG:jhard-0250-f15.png]阶完美点”，若二次函数[IMG:jhard-0250-f16.png]的图象上有且只有一个“2阶完美点”，求实数[IMG:jhard-0250-f17.png]的取值范围．[IMG:jhard-0250-f18.png]','','','','imported-junior-hard','approved','通用','压轴');
