INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jhard-0252','math','初中',0,'jkp-0396','short_answer',0.78,'（2025•潍坊）如图，在平面直角坐标系中，二次函数[IMG:jhard-0252-f1.png]与正比例函数[IMG:jhard-0252-f2.png]的图象都经过点[IMG:jhard-0252-f3.png]，点[IMG:jhard-0252-f4.png]为二次函数图象上点[IMG:jhard-0252-f5.png]与点[IMG:jhard-0252-f6.png]之间的一点，过点[IMG:jhard-0252-f7.png]作[IMG:jhard-0252-f8.png]轴的垂线，交[IMG:jhard-0252-f9.png]于点[IMG:jhard-0252-f10.png]，交[IMG:jhard-0252-f11.png]轴于点[IMG:jhard-0252-f12.png]．（1）若点[IMG:jhard-0252-f13.png]为该二次函数的顶点，①求二次函数的表达式；②求线段[IMG:jhard-0252-f14.png]长度的最大值．（2）若该二次函数与[IMG:jhard-0252-f15.png]轴的一交点为[IMG:jhard-0252-f16.png]，且[IMG:jhard-0252-f17.png]，求[IMG:jhard-0252-f18.png]的取值范围．[IMG:jhard-0252-f19.png]','','','','imported-junior-hard','approved','通用','压轴');
INSERT OR IGNORE INTO questions (id, subject, stage, grade_level, knowledge_point_id, type, difficulty, content, options, answer, analysis, source, review_status, textbook_version, level) VALUES ('jhard-0253','math','初中',0,'jkp-0349','short_answer',0.78,'（2025•潍坊）黄金分割被广泛应用在建筑、艺术等领域，我国早在战国时期就已知道并能应用黄金分割．中国澳门发行的邮票小型张《科学与科技[IMG:jhard-0253-f1.png]黄金比例》（如图[IMG:jhard-0253-f2.png]就是用黄金分割比作为主题设计的．[IMG:jhard-0253-f3.png]                      [IMG:jhard-0253-f4.png]【阅读观察】材料1：黄金分割点的定义如图2，若线段[IMG:jhard-0253-f5.png]上的点[IMG:jhard-0253-f6.png]满足[IMG:jhard-0253-f7.png]，则点[IMG:jhard-0253-f8.png]称作线段[IMG:jhard-0253-f9.png]的黄金分割点，其中[IMG:jhard-0253-f10.png]的比值称作黄金分割比[IMG:jhard-0253-f11.png]，而[IMG:jhard-0253-f12.png]的比值为[IMG:jhard-0253-f13.png]，[IMG:jhard-0253-f14.png]与[IMG:jhard-0253-f15.png]互为倒数．[IMG:jhard-0253-f16.png]材料2：黄金分割点的作法（借助尺规作图可以用不同方法确定图2中线段[IMG:jhard-0253-f17.png]的黄金分割点[IMG:jhard-0253-f18.png]方法1：如图3，①过点[IMG:jhard-0253-f19.png]作[IMG:jhard-0253-f20.png]；②在直线[IMG:jhard-0253-f21.png]上截取[IMG:jhard-0253-f22.png]，连接[IMG:jhard-0253-f23.png]；③在[IMG:jhard-0253-f24.png]上截取[IMG:jhard-0253-f25.png]；④在[IMG:jhard-0253-f26.png]上截取[IMG:jhard-0253-f27.png]．点[IMG:jhard-0253-f28.png]即为所求．[IMG:jhard-0253-f29.png]方法2：如图4，①以[IMG:jhard-0253-f30.png]为边作正方形[IMG:jhard-0253-f31.png]；②取[IMG:jhard-0253-f32.png]中点[IMG:jhard-0253-f33.png]，连接[IMG:jhard-0253-f34.png]；③以点[IMG:jhard-0253-f35.png]为圆心，[IMG:jhard-0253-f36.png]为半径作圆弧，与[IMG:jhard-0253-f37.png]的延长线交于点[IMG:jhard-0253-f38.png]；④以[IMG:jhard-0253-f39.png]为边在[IMG:jhard-0253-f40.png]一侧作正方形[IMG:jhard-0253-f41.png]，[IMG:jhard-0253-f42.png]交[IMG:jhard-0253-f43.png]于点[IMG:jhard-0253-f44.png]，可得[IMG:jhard-0253-f45.png]．点[IMG:jhard-0253-f46.png]即为所求．[IMG:jhard-0253-f47.png]【思考探究】（1）说明图3中[IMG:jhard-0253-f48.png]；（2）用不同于（1）的方法，说明图4中[IMG:jhard-0253-f49.png]．【迁移拓展】如图5，作圆内接正五边形：①作[IMG:jhard-0253-f50.png]的两条互相垂直的半径[IMG:jhard-0253-f51.png]和[IMG:jhard-0253-f52.png]，取[IMG:jhard-0253-f53.png]的中点[IMG:jhard-0253-f54.png]，连接[IMG:jhard-0253-f55.png]；②作[IMG:jhard-0253-f56.png]的平分线，交[IMG:jhard-0253-f57.png]于点[IMG:jhard-0253-f58.png]；③过点[IMG:jhard-0253-f59.png]作[IMG:jhard-0253-f60.png]的垂线，交[IMG:jhard-0253-f61.png]于点[IMG:jhard-0253-f62.png]，[IMG:jhard-0253-f63.png]，连接[IMG:jhard-0253-f64.png]，[IMG:jhard-0253-f65.png]；④截取[IMG:jhard-0253-f66.png]，[IMG:jhard-0253-f67.png]，连接[IMG:jhard-0253-f68.png]，[IMG:jhard-0253-f69.png]，[IMG:jhard-0253-f70.png]．五边形[IMG:jhard-0253-f71.png]即为所求．（3）若[IMG:jhard-0253-f72.png]，根据以上作法，证明；[IMG:jhard-0253-f73.png]．','','','','imported-junior-hard','approved','通用','压轴');
